const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const authHeader = headers.authorization || '';

// QUAN TRỌNG: Gán cứng URL để tránh lỗi access denied đối với $env
const frontendUrl = 'https://approvehub.internalautomation.io.vn';

const leaveId = body.leaveId || body._id || '';
const leave_date = (body.leave_date || body.leaveDate || '').trim();
const leave_days = parseInt(body.leave_days || body.leaveDays || 0);
const reason = body.reason || '';
const employeeName = body.employeeName || body.employee_name || '';
const employeeEmail = body.employeeEmail || body.employee_email || '';
const department = body.department || '';
const managerEmail = body.managerEmail || '';
const hrEmail = body.hrEmail || '';

// Tokens và Links
const managerApprovalToken = body.managerApprovalToken || '';
const hrApprovalToken = body.hrApprovalToken || '';

let managerApprovalLink = body.managerApprovalLink ||
  `${frontendUrl}/approval-page.html?token=${encodeURIComponent(managerApprovalToken)}`;
managerApprovalLink += `&n8nResumeUrl=${encodeURIComponent($execution.resumeUrl)}`;

const hrApprovalLink = body.hrApprovalLink || 
  (hrApprovalToken ? `${frontendUrl}/approval-page.html?token=${encodeURIComponent(hrApprovalToken)}&hr=true` : '');

// Logic nghiệp vụ
const wasResubmitted = body.wasResubmitted === true || body.wasResubmitted === 'true';
const needsHrNotify = (leave_days > 3) && (hrEmail && hrEmail !== '');

// Xử lý định dạng ngày tháng
const rawEndDate = (body.end_date || body.endDate || '').trim();
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ json: {
  token: authHeader.replace('Bearer ', ''),
  leaveId,
  leave_date,
  leaveDateDisplay: fmt(leave_date),
  end_date: rawEndDate,
  endDateDisplay: fmt(rawEndDate),
  leave_days,
  reason,
  employeeName,
  employeeEmail,
  department,
  managerEmail,
  hrEmail,
  managerApprovalToken,
  hrApprovalToken,
  managerApprovalLink,
  hrApprovalLink,
  wasResubmitted,
  needsHrNotify,
  frontendUrl
} }];

